import zipfile, xml.etree.ElementTree as ET, glob, os
NS={'m':'http://schemas.openxmlformats.org/spreadsheetml/2006/main','r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}
for path in glob.glob(r'd:\CodeRepos\endfield_blueprint_tool\docs\*.xlsx'):
    print('\n###',os.path.basename(path))
    with zipfile.ZipFile(path) as z:
        shared=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            root=ET.fromstring(z.read('xl/sharedStrings.xml'))
            for si in root.findall('m:si',NS): shared.append(''.join(t.text or '' for t in si.iter('{%s}t'%NS['m'])))
        wb=ET.fromstring(z.read('xl/workbook.xml'))
        rel=ET.fromstring(z.read('xl/_rels/workbook.xml.rels'))
        rels={x.attrib['Id']:x.attrib['Target'] for x in rel}
        for sh in wb.find('m:sheets',NS):
            target=rels[sh.attrib['{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id']]
            target='xl/'+target.lstrip('/') if not target.startswith('xl/') else target
            root=ET.fromstring(z.read(target))
            print('\nSHEET',sh.attrib['name'])
            for row in root.findall('.//m:sheetData/m:row',NS):
                vals=[]
                for c in row.findall('m:c',NS):
                    v=c.find('m:v',NS); val='' if v is None else v.text
                    if c.attrib.get('t')=='s' and val: val=shared[int(val)]
                    elif c.attrib.get('t')=='inlineStr': val=''.join(t.text or '' for t in c.iter('{%s}t'%NS['m']))
                    vals.append(f"{c.attrib.get('r')}={val}")
                print(' | '.join(vals))
