import zipfile, xml.etree.ElementTree as ET, os
p=r'd:\CodeRepos\endfield_blueprint_tool\docs\终末地产线限制.docx'
with zipfile.ZipFile(p) as z:
    root=ET.fromstring(z.read('word/document.xml'))
ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
for child in root.find('w:body',ns):
    tag=child.tag.rsplit('}',1)[-1]
    if tag=='p':
        text=''.join(x.text or '' for x in child.iter('{%s}t'%ns['w']))
        if text.strip(): print(text)
    elif tag=='tbl':
        print('[TABLE]')
        for tr in child.findall('w:tr',ns):
            print(' | '.join(''.join(x.text or '' for x in tc.iter('{%s}t'%ns['w'])) for tc in tr.findall('w:tc',ns)))
